contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        uint256 balBefore = c.balances(address(this));
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balances(address(this));
        uint256 cBalAfter = address(c).balance;
        uint256 minDeposit = c.MinDeposit();

        if (amount >= minDeposit) {
