contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint dep, uint out) public payable {
        require(dep >= c.MinDeposit());
        require(address(this).balance >= dep);

        c.Deposit{value: dep}();

        uint beforeBal = address(this).balance;
        uint b0 = c.balances(address(this));

        bool reverted;
        try c.CashOut(out) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint b1 = c.balances(address(this));
        uint afterBal = address(this).balance;

        assert(
            reverted
                ? (b1 == b0 && afterBal == beforeBal)
                : (b1 + out == b0 && afterBal == beforeBal + out)
        );
    }

    receive() external payable {}
}

